/**
 * `src/native/generated/names.ts`: every enum vocabulary as an `as const`
 * array and its union, and every enum value map as an `as const` object and
 * the union of its values.
 *
 * Authored as TypeScript and run directly by Node's type stripping, so this
 * file must stay erasable (no enums, namespaces or parameter properties).
 */
import type { NameVocabulary } from '../names.ts';

const NAMES_HEADER = `// SPDX-License-Identifier: MIT AND LGPL-2.1-or-later
// Generated by packages/hamlib-codegen from the pinned Hamlib release's src/misc.c, src/rig.c and rig.h.
// The names are Hamlib's own (LGPL-2.1-or-later); the code is MIT.
// Do not edit: run \`mise run generate\`.`;

/** A TypeScript string literal. */
function quote(text: string): string {
  return `'${text.replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`;
}

/** `appendix` is further generated declarations the file carries (the line settings). */
export function emitNames(vocabularies: readonly NameVocabulary[], appendix: readonly string[] = []): string {
  const lines = [NAMES_HEADER, ''];

  for (const vocabulary of vocabularies) {
    const { names, values } = vocabulary.record;

    if (names) {
      lines.push(`/** Every accepted name, aliases included, from ${vocabulary.source}. */`);
      lines.push(`export const ${names.constant} = [`);
      lines.push(...vocabulary.names.map((name) => `  ${quote(name)},`));
      lines.push('] as const;');
      lines.push('');
      lines.push(`/** One of {@link ${names.constant}}. */`);
      lines.push(`export type ${names.type} = (typeof ${names.constant})[number];`);
      lines.push('');
    }

    if (values) {
      const constants = vocabulary.constants ?? [];

      lines.push(`/** The value of each name, from ${vocabulary.source}. */`);
      lines.push(`export const ${values.constant} = {`);

      vocabulary.names.forEach((name, index) => {
        const value = constants[index]?.value;

        if (value === undefined || !Number.isSafeInteger(value)) {
          throw new Error(`${vocabulary.record.enumName}: ${name} has no exact value`);
        }

        lines.push(`  ${/^[A-Za-z_]\w*$/.test(name) ? name : quote(name)}: ${value},`);
      });

      lines.push('} as const;');
      lines.push('');
      lines.push(`/** One of the values of {@link ${values.constant}}. */`);
      lines.push(`export type ${values.type} = (typeof ${values.constant})[keyof typeof ${values.constant}];`);
      lines.push('');
    }
  }

  return [...lines, ...appendix].join('\n');
}

/**
 * Hamlib's text for each error code, as a tuple indexed by the code, so the
 * TypeScript layer reports what `rigerror()` would.  The codes have to be
 * exactly the table's indexes.
 */
export function errorMessageConstants(vocabularies: readonly NameVocabulary[], messages: readonly string[]): string[] {
  const errcodes = vocabularies.find((vocabulary) => vocabulary.record.enumName === 'rig_errcode_e');
  const values = errcodes?.constants?.map((constant) => constant.value) ?? [];

  if (!errcodes?.record.values || values.length !== messages.length || values.some((value, index) => value !== index)) {
    throw new Error(`rigerror_table[] has ${messages.length} messages, rig_errcode_e has codes ${values.join(', ')}`);
  }

  return [
    `/** Hamlib's text for each code of {@link ${errcodes.record.values.constant}}, indexed by the code, from \`rigerror_table[]\` in Hamlib's src/rig.c. */`,
    'export const RIG_ERROR_MESSAGES = [',
    ...messages.map((message) => `  ${quote(message)},`),
    `] as const satisfies Readonly<Record<${errcodes.record.values.type}, string>>;`,
    '',
  ];
}

const TRANSPORT_HEADER = `// SPDX-License-Identifier: MIT
// Generated by packages/hamlib-codegen from native/web_serial.h.
// Do not edit: run \`mise run generate\`.`;

/**
 * `native/generated/transport.d.ts`: the transport contract's constants as
 * ambient `const enum`s, so the JS library speaks the same codes and bits as
 * `native/web_serial.c` without importing anything.
 */
export function emitTransportTypes(vocabularies: readonly NameVocabulary[], appendix: readonly string[] = []): string {
  const lines = [TRANSPORT_HEADER, '', ...appendix];

  for (const vocabulary of vocabularies) {
    const type = vocabulary.record.constEnum;

    if (type === undefined) {
      continue;
    }

    lines.push(`/** From ${vocabulary.source}. */`);
    lines.push(`declare const enum ${type} {`);
    vocabulary.names.forEach((name, index) => {
      lines.push(`  ${name} = ${vocabulary.constants?.[index]?.value},`);
    });
    lines.push('}', '');
  }

  return lines.join('\n');
}
